        subtype: str(ev.subtype),
        isError: ev.is_error === true,
        numTurns: typeof ev.num_turns === "number" ? ev.num_turns : null,
        terminalReason: str(ev.terminal_reason ?? ev.stop_reason) || null,
      };
    }
  }
  return { calls, results, finalText, turns, result };
